1108: fn check_rust_only_files(issues: &mut Vec<String>) {
1109:     for forbidden in ["pyproject.toml", "requirements-dev.txt"] {
1110:         if Path::new(forbidden).exists() {
1111:             issues.push(format!(
1112:                 "FAIL: python-tooling-present: {forbidden} must not exist."
1113:             ));
1114:         }
1115:     }
1116:     for directory in ["scripts", "src/codebase_graph"] {
1117:         if Path::new(directory).exists() {
1118:             issues.push(format!(
1119:                 "FAIL: python-surface-present: {directory} must not exist."
1120:             ));
1121:         }
1122:     }
1123:     for path in files_under(Path::new(".")) {
1124:         let relative = path.strip_prefix(".").unwrap_or(&path);
1125:         if has_generated_component(relative) {
1126:             continue;
1127:         }
1128:         if path.extension().is_some_and(|extension| extension == "py") {
1129:             let text_path = relative.to_string_lossy();
1130:             match is_docs_helper_path(Path::new("."), &path) {
1131:                 Ok(true) => {}
1132:                 Ok(false) => issues.push(format!(
1133:                     "FAIL: python-file-present: {} must not be maintained source.",
1134:                     text_path
1135:                 )),
1136:                 Err(error) => {
1137:                     issues.push(format!("FAIL: docs-python-exception-unavailable: {error}."))
1138:                 }
1139:             }
1140:         }
1141:     }
1142: }
