1005: fn is_docs_helper_path(root: &Path, candidate: &Path) -> Result<bool, String> {
1006:     let relative = if candidate.is_absolute() {
1007:         if let Ok(relative) = candidate.strip_prefix(root) {
1008:             relative.to_path_buf()
1009:         } else {
1010:             let repository_root = root.canonicalize().map_err(|error| {
1011:                 format!(
1012:                     "cannot resolve repository root {} for the docs Python exception: {error}",
1013:                     root.display()
1014:                 )
1015:             })?;
1016:             let Ok(relative) = candidate.strip_prefix(&repository_root) else {
1017:                 return Ok(false);
1018:             };
1019:             relative.to_path_buf()
1020:         }
1021:     } else {
1022:         candidate
1023:             .strip_prefix(root)
1024:             .unwrap_or(candidate)
1025:             .to_path_buf()
1026:     };
1027: 
1028:     let mut components = Vec::new();
1029:     for component in relative.components() {
1030:         let std::path::Component::Normal(name) = component else {
1031:             return Ok(false);
1032:         };
1033:         components.push(name.to_os_string());
1034:     }
1035:     if components.len() < 2
1036:         || components[0].to_str() != Some("docs")
1037:         || relative.extension() != Some(std::ffi::OsStr::new("py"))
1038:     {
1039:         return Ok(false);
1040:     }
1041: 
1042:     let repository_root = root.canonicalize().map_err(|error| {
1043:         format!(
1044:             "cannot resolve repository root {} for the docs Python exception: {error}",
1045:             root.display()
1046:         )
1047:     })?;
1048:     let mut path = repository_root.clone();
1049:     for (index, component) in components.iter().enumerate() {
1050:         path.push(component);
1051:         let metadata = fs::symlink_metadata(&path).map_err(|error| {
1052:             format!(
1053:                 "cannot inspect docs Python exception path {}: {error}; no exception is granted",
1054:                 path.display()
1055:             )
1056:         })?;
1057:         if metadata.file_type().is_symlink() {
1058:             return Err(format!(
1059:                 "docs Python exception rejects symlink path {}; no exception is granted",
1060:                 path.display()
1061:             ));
1062:         }
1063:         let is_last = index + 1 == components.len();
1064:         if (is_last && !metadata.is_file()) || (!is_last && !metadata.is_dir()) {
1065:             return Ok(false);
1066:         }
1067:     }
1068: 
1069:     let docs = repository_root.join("docs");
1070:     let real_docs = docs.canonicalize().map_err(|error| {
1071:         format!(
1072:             "cannot resolve literal docs directory {}: {error}; no exception is granted",
1073:             docs.display()
1074:         )
1075:     })?;
1076:     if real_docs.parent() != Some(repository_root.as_path()) {
1077:         return Err(format!(
1078:             "docs directory {} does not resolve to the repository's literal docs directory; no exception is granted",
1079:             docs.display()
1080:         ));
1081:     }
1082:     let real_candidate = path.canonicalize().map_err(|error| {
1083:         format!(
1084:             "cannot resolve docs Python exception path {}: {error}; no exception is granted",
1085:             path.display()
1086:         )
1087:     })?;
1088:     if real_candidate.strip_prefix(&real_docs).is_err() {
1089:         return Err(format!(
1090:             "docs Python exception path {} resolves outside literal docs; no exception is granted",
1091:             path.display()
1092:         ));
1093:     }
1094: 
1095:     Ok(true)
1096: }
