1098: fn has_generated_component(path: &Path) -> bool {
1099:     path.components().any(|component| {
1100:         matches!(
1101:             component,
1102:             std::path::Component::Normal(name)
1103:                 if matches!(name.to_str(), Some(".git" | "target" | ".codebaseGraph" | ".kwiki"))
1104:         )
1105:     })
1106: }
